mapper.select:
SELECT a.id, a.quantity, a.serial_number, a.net_weight, a.specification,
a.name,
16 productType,
b.task_type_enum productType, a.monomer_id, a.area_id,
ifnull(b.task_quantity,0)task_quantity, ifnull(b.in_production_quantity,0)in_production_quantity, ifnull( a.produced_quantity,0)complete_quantity FROM
tech_artifact a
tech_assemble a
tech_machine_part a
LEFT JOIN ( SELECT a.product_id, a.task_type_enum, ifnull( SUM( a.task_quantity ), 0 ) task_quantity, ifnull( SUM( a.in_production_quantity ), 0 ) in_production_quantity, ifnull( SUM( a.complete_quantity ), 0 ) complete_quantity FROM mes_building_task a
a.bool_delete_enum = FALSE
AND a.task_type_enum = #{productType}
AND a.factory_id = #{factoryId}
AND a.product_process_id IN
#(productProcessId)
AND a.monomer_id = #{monomerId}
AND a.project_id = #{projectId}
GROUP BY a.product_id, a.task_type_enum ) b ON a.id = b.product_id LEFT JOIN ( SELECT a.product_id, a.task_type_enum, ifnull( SUM( a.quantity ), 0 ) quantity, ifnull( SUM( a.inspection_quantity ), 0 ) inspection_quantity FROM mes_building_produce_team_report a
LEFT JOIN tech_artifact product on product.id = a.product_id and product.bool_delete_enum =0
AND product.monomer_id = #{monomerId}
AND product.project_id = #{projectId}
LEFT JOIN tech_assemble product on product.id = a.product_id and product.bool_delete_enum =0
AND product.monomer_id = #{monomerId}
AND product.project_id = #{projectId}
LEFT JOIN tech_machine_part product on product.id = a.product_id and product.bool_delete_enum =0
AND product.monomer_id = #{monomerId}
AND product.project_id = #{projectId}
a.bool_delete_enum = FALSE
AND a.task_type_enum = #{productType}
AND product.monomer_id = #{monomerId}
AND product.project_id = #{projectId}
GROUP BY a.product_id, a.task_type_enum ) c ON a.id = c.product_id
a.bool_delete_enum=FALSE
AND a.bool_scheduling_enum =true
AND (a.produced_quantity =0) AND (c.quantity =0 or c.quantity is null)
AND a.produced_quantity < a.quantity AND (c.quantity > 0)
AND a.produced_quantity = a.quantity
AND c.inspection_quantity< c.quantity AND c.quantity > 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.name like CONCAT('%', #{name},'%')
AND a.serial_number like CONCAT('%', #{serialNumber},'%')
AND a.specification like CONCAT('%', #{specification},'%')
AND a.material like CONCAT('%', #{material},'%')
AND a.steel_spec =#{steelSpec}
and a.relation_type in (2,16)

SELECT b.id processId, b.`name`, a.complete_quantity, a.inspection_quantity FROM ( SELECT mp.process_id, mp.sequence, SUM( mp.complete_quantity ) complete_quantity, SUM( mp.inspection_quantity ) inspection_quantity FROM mes_building_task_process mp where mp.task_id IN
#{taskId}
AND task_type_enum = #{type} AND mp.bool_delete_enum = 0 GROUP BY mp.process_id, mp.sequence ORDER BY sequence ) AS a LEFT JOIN mes_building_process b ON b.id = a.process_id AND b.bool_delete_enum = 0

SELECT ta.project_id 'project.id', ta.monomer_id 'monomer.id', ta.area_id 'areaDetail.id', a.date, a.quantity, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', ta.`name` `name`, ta.serial_number, ta.net_weight, ta.gross_weight, ta.material, ta.drawing_number, ta.length, ta.surface_area, ta.specification, ta.net_weight*a.quantity total_net_weight, ta.gross_weight*a.quantity total_gross_weight FROM ( SELECT product_id, DATE_FORMAT(create_time, '%Y/%m/%d' ) date,SUM( a.quantity ) quantity FROM mes_building_complete a WHERE product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND date(create_time) >= date(#{startDate})
AND date(create_time) <= date(#{endDate})
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
GROUP BY product_id,date ) AS a LEFT JOIN tech_artifact ta ON a.product_id = ta.id AND ta.bool_delete_enum = FALSE LEFT JOIN contract_project cp ON cp.id = ta.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = ta.area_id AND pd.bool_delete_enum = FALSE
AND ta.project_id in
#{projectId}
AND ta.monomer_id=#{monomerId}
AND ta.area_id=#{areaId}
AND ta.name like CONCAT('%',#{name},'%')
AND ta.serial_number like CONCAT('%',#{serialNumber},'%')
AND ta.material like CONCAT('%',#{material},'%')
AND ta.specification like CONCAT('%',#{specification},'%')

SELECT ta.project_id 'project.id', ta.monomer_id 'monomer.id', ta.area_id 'areaDetail.id', a.date, a.quantity, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', ta.`name` `name`, ta.serial_number, ta.material, ta.width, ta.length, ta.category, ta.color, ta.thickness, ta.plate, ta.length*a.quantity total_length, ta.length*ta.width*a.quantity total_area FROM ( SELECT product_id, DATE_FORMAT(create_time, '%Y/%m/%d' ) date,SUM( a.quantity ) quantity FROM mes_building_complete a WHERE product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
AND date (create_time) >= date(#{startDate})
AND date (create_time) <= date(#{endDate})
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
GROUP BY product_id,date ) AS a LEFT JOIN tech_enclosure ta ON a.product_id = ta.id AND ta.bool_delete_enum = FALSE LEFT JOIN contract_project cp ON cp.id = ta.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = ta.area_id AND pd.bool_delete_enum = FALSE
AND ta.name like CONCAT('%', #{name},'%')
AND ta.serial_number like CONCAT('%', #{serialNumber},'%')
AND ta.plate like CONCAT('%', #{plate},'%')
AND ta.category in (1,3)
AND ta.category = #{category}

select.if:
SELECT DATE(a.ask_complete_time) ask_complete_time, IFNULL(SUM(a.task_quantity),0)task_quantity, IFNULL(SUM(a.complete_quantity),0)complete_quantity, IFNULL(SUM(a.task_quantity*a.length ),0) task_length, IFNULL(SUM(a.complete_quantity*a.length ),0) complete_length, IFNULL(SUM(a.task_quantity*a.net_weight ),0) task_net_weight, IFNULL(SUM(a.complete_quantity*a.net_weight ),0)complete_net_weight
,IFNULL(SUM(a.task_quantity*a.gross_weight ),0) task_gross_weight, IFNULL(SUM(a.complete_quantity*a.gross_weight ),0)complete_gross_weight
FROM ( SELECT a.id, a.ask_complete_time, a.product_id, a.product_type, a.task_quantity, ta.length, ta.net_weight,
ta.gross_weight,
(SELECT SUM(quantity) FROM mes_building_complete WHERE DATE(create_time)<=DATE(a.ask_complete_time) AND a.id=task_id) complete_quantity FROM mes_building_task a
LEFT JOIN tech_assemble ta ON ta.id=a.product_id
LEFT JOIN tech_artifact ta ON ta.id=a.product_id
LEFT JOIN tech_machine_part ta ON ta.id=a.product_id
a.task_type_enum=#{productType}
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND ( a.complete_quantity < a.task_quantity OR a.ask_complete_time < a.complete_time ) AND date(a.ask_complete_time)<date(NOW()) AND DATE_FORMAT( a.ask_complete_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
) AS a GROUP BY date(ask_complete_time);

SELECT DATE(a.ask_complete_time) ask_complete_time, IFNULL(SUM(a.task_quantity),0)task_quantity, IFNULL(SUM(a.complete_quantity),0)complete_quantity, IFNULL(SUM(a.task_quantity*a.length ),0) task_length, IFNULL(SUM(a.task_quantity*a.length*a.width ),0) task_area, IFNULL(SUM(a.complete_quantity*a.length ),0)complete_length, IFNULL(SUM(a.complete_quantity*a.length*a.width ),0)complete_area FROM ( SELECT a.id, a.ask_complete_time, a.product_id, a.product_type, a.task_quantity, ta.category, ta.length, ta.width, (SELECT SUM(quantity) FROM mes_building_complete WHERE DATE(create_time)<=DATE(a.ask_complete_time) AND a.id=task_id) complete_quantity FROM mes_building_task a LEFT JOIN tech_enclosure ta ON ta.id=a.product_id
a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND ta.category=#{category}
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
and ( a.complete_quantity < a.task_quantity OR a.ask_complete_time < a.complete_time ) AND date(a.ask_complete_time)<date(NOW()) AND DATE_FORMAT( a.ask_complete_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
) AS a GROUP BY date(ask_complete_time);

SELECT a.product_id,
a.material, a.specification, a.serial_number, a.project_id 'project.id', a.monomer_id 'monomer.id', a.area_id 'areaDetail.id', a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', a.ask_complete_time, IFNULL(SUM(a.task_quantity),0)task_quantity, IFNULL(SUM(a.complete_quantity),0)complete_quantity, IFNULL(SUM(a.task_quantity*a.length ),0) task_length, IFNULL(SUM(a.complete_quantity*a.length ),0)complete_length, IFNULL(SUM(a.task_quantity*a.net_weight ),0) task_net_weight, IFNULL(SUM(a.complete_quantity*a.net_weight ),0)complete_net_weight
, a.`name`, IFNULL(SUM(a.task_quantity*a.gross_weight ),0) task_gross_weight, IFNULL(SUM(a.complete_quantity*a.gross_weight ),0)complete_gross_weight
FROM ( SELECT a.id, a.ask_complete_time, a.product_id, a.product_type, a.project_id, a.monomer_id, a.factory_id, a.workshop_id, a.production_line_id, a.area_id, ta.length,
ta.`name`, ta.gross_weight,
ta.material, ta.specification, ta.net_weight, ta.serial_number, a.task_quantity, (SELECT SUM(quantity) FROM mes_building_complete WHERE DATE(create_time)<=DATE(a.ask_complete_time) AND a.id=task_id) complete_quantity FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id=a.product_id LEFT JOIN tech_assemble ta ON ta.id=a.product_id LEFT JOIN tech_machine_part ta ON ta.id=a.product_id WHERE a.bool_delete_enum=FALSE AND a.product_type=#{productType} AND ( a.complete_quantity < a.task_quantity OR a.ask_complete_time < a.complete_time ) AND date(a.ask_complete_time)<date(NOW()) AND DATE_FORMAT( a.ask_complete_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )) AS a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id AND mbpl.bool_delete_enum = FALSE WHERE DATE(a.ask_complete_time)=DATE(#{dateTime})
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
GROUP BY a.product_id,
a.`name`,
a.material, a.specification, a.serial_number, a.project_id, a.monomer_id, a.area_id, a.factory_id, a.workshop_id, a.production_line_id, cp.`name`, cp.short_name, cp.serial_number, pm.`name`, pd.`name`, mbf.`name`, mbw.`name`, mbpl.`name`, a.ask_complete_time

SELECT a.product_id, a.`name`, a.material, a.plate, a.color, a.ask_complete_time, a.project_id 'project.id', a.monomer_id 'monomer.id', a.area_id 'areaDetail.id', a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', IFNULL(SUM(a.task_quantity),0)task_quantity, IFNULL(SUM(a.complete_quantity),0)complete_quantity, IFNULL(SUM(a.task_quantity*a.length ),0) task_length, IFNULL(SUM(a.task_quantity*a.length*a.width ),0) task_area, IFNULL(SUM(a.complete_quantity*a.length ),0)complete_length, IFNULL(SUM(a.complete_quantity*a.length*a.width ),0)complete_area FROM ( SELECT a.id, a.ask_complete_time, a.product_id, ta.`name`, ta.material, ta.plate, ta.color, a.task_quantity, a.project_id, a.monomer_id, a.factory_id, a.workshop_id, a.production_line_id, a.area_id, ta.length, ta.width, (SELECT SUM(quantity) FROM mes_building_complete WHERE DATE(create_time)<=DATE(a.ask_complete_time) AND a.id=task_id) complete_quantity FROM mes_building_task a LEFT JOIN tech_enclosure ta ON ta.id=a.product_id WHERE a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND ta.category=#{category} and ( a.complete_quantity < a.task_quantity OR a.ask_complete_time < a.complete_time ) AND date(a.ask_complete_time)<date(NOW()) AND DATE_FORMAT( a.ask_complete_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )) AS a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id AND mbpl.bool_delete_enum = FALSE WHERE DATE(a.ask_complete_time)=DATE(#{dateTime})
AND a.factory_id=#{factoryId}
AND a.workshop_id=#{workshopId}
AND a.productionLine_id=#{productionLineId}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
GROUP BY a.product_id, a.`name`, a.material, a.plate, a.color, a.ask_complete_time, a.project_id, a.monomer_id , a.area_id , a.factory_id , a.workshop_id , a.production_line_id , cp.`name` , cp.short_name , cp.serial_number , pm.`name` , pd.`name` , mbf.`name` , mbw.`name` , mbpl.`name` ,

mapper.select:
SELECT IFNULL(SUM(t.task_quantity),0) quantity,
IFNULL(SUM(a.net_weight * t.task_quantity),0) mete FROM mes_building_task t INNER JOIN tech_artifact a ON a.id = t.product_id AND t.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and a.bool_delete_enum = 0
IFNULL(SUM(e.length * t.task_quantity / 1000),0) mete FROM mes_building_task t INNER JOIN tech_enclosure e ON e.id = t.product_id AND t.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and e.bool_delete_enum = 0
and t.bool_delete_enum = 0
AND t.monomer_id = #{monomerId}
AND t.factory_id = #{factoryId}
AND t.product_type = #{productType}

SELECT a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', a.product_type FROM( SELECT a.factory_id, a.workshop_id, a.production_line_id, a.product_type FROM ( SELECT a.factory_id, a.workshop_id, a.production_line_id, a.task_quantity, a.product_type FROM mes_building_task a
a.task_type_enum IN (1,2,16) and a.bool_delete_enum = FALSE
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.factory_id=#{factoryId}
AND a.task_type_enum=#{productType}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
) AS a GROUP BY a.factory_id, a.workshop_id, a.production_line_id, a.product_type) as a LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id

SELECT a.product_id, ta.serial_number,
ta.name,
ta.specification, ta.material, ta.project_id 'project.id', ta.monomer_id 'monomer.id', ta.area_id 'areaDetail.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', a.product_type, IFNULL(a.quantity,0) complete_quantity, IFNULL(a.task_quantity,0) task_quantity, IFNULL(a.quantity * ta.net_weight,0) complete_net_weight, IFNULL(a.task_quantity * ta.net_weight,0) task_net_weight FROM ( SELECT a.quantity, task.process_id, task.task_quantity, task.product_id, task.product_type FROM mes_building_task_process task LEFT JOIN ( SELECT sum( a.inspection_quantity ) quantity, a.task_process_id FROM mes_building_produce_team_report a
a.product_type = #{productType} and a.bool_delete_enum = FALSE
AND a.process_id=#{processId}
AND a.product_type=#{productType}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
GROUP BY a.task_process_id ) a ON a.task_process_id = task.id
task.bool_delete_enum = FALSE
AND task.project_id in
#{projectId}
and task.project_id=#{projectId}
AND task.process_id=#{processId}
and task.production_line_id=#{productionLineId}
AND task.product_type=#{productType}
AND DATE(task.create_time)>=DATE(#{startDate})
AND DATE(task.create_time)<=DATE(#{endDate})
) a LEFT JOIN mes_building_process process ON a.process_id = process.id
LEFT JOIN tech_assemble ta ON ta.id=a.product_id
LEFT JOIN tech_artifact ta ON ta.id=a.product_id
LEFT JOIN tech_machine_part ta ON ta.id=a.product_id
LEFT JOIN tech_enclosure ta ON ta.id=a.product_id
LEFT JOIN contract_project cp ON cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id LEFT JOIN plan_area pd ON pd.id = ta.area_id

SELECT a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', a.product_type, IFNULL(a.task_quantity,0)task_quantity, IFNULL(a.task_length,0)task_length, IFNULL(a.task_area,0)task_area, IFNULL(a.complete_quantity,0)complete_quantity, IFNULL(a.complete_length,0)complete_length, IFNULL(a.complete_area ,0)complete_area FROM ( SELECT a.factory_id, a.workshop_id, a.production_line_id, a.product_type, SUM( a.task_quantity ) task_quantity, SUM( a.task_quantity *a.length) task_length, SUM( a.task_quantity *a.area) task_area, SUM( a.complete_quantity ) complete_quantity, SUM( a.complete_quantity *a.length) complete_length, SUM( a.complete_quantity *a.area) complete_area FROM ( SELECT a.factory_id, a.workshop_id, a.production_line_id, a.product_id, a.task_quantity, a.product_type, b.length, b.length*b.width area, (SELECT SUM(quantity) FROM mes_building_complete
bool_delete_enum=FALSE and product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and task_id = a.id
AND DATE(create_time)>=DATE(#{startDate})
AND DATE(create_time)<=DATE(#{endDate})
)complete_quantity FROM mes_building_task a LEFT JOIN tech_enclosure b ON a.product_id = b.id
a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
AND a.factory_id=#{factoryId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
) AS a GROUP BY a.factory_id, a.workshop_id, a.production_line_id )as a LEFT JOIN mes_building_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = a.production_line_id AND mbpl.bool_delete_enum = FALSE

SELECT a.factory_id, a.workshop_id, a.production_line_id, a.project_id, a.monomer_id, a.area_id, a.product_id, a.product_type, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', b.`name`, b.serial_number, b.category, a.complete_time, b.plate, b.color, b.material, b.length, b.width, b.thickness, a.task_quantity task_quantity, a.task_quantity * b.length task_length, a.task_quantity * b.length * b.width task_area, a.complete_quantity complete_quantity, a.complete_quantity * b.length complete_length, a.complete_quantity * b.length * b.width complete_area FROM ( SELECT SUM( quantity ) complete_quantity, DATE(a.create_time) complete_time, a.product_type, a.task_id, b.workshop_id, b.production_line_id, b.product_id, b.project_id, b.monomer_id, b.factory_id, b.area_id, b.task_quantity FROM mes_building_complete a LEFT JOIN mes_building_task b ON a.task_id = b.id
a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
AND a.project_id in
#{projectId}
AND a.project_id=#{projectId}
and a.production_line_id =#{productionLineId}
AND DATE(b.create_time)>=DATE(#{startDate})
AND DATE(b.create_time)<=DATE(#{endDate})
GROUP BY a.task_id, DATE(a.create_time) ) AS a LEFT JOIN tech_enclosure b ON a.product_id = b.id LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE;

SELECT a.id id, t.id task_id, t.factory_id, t.workshop_id, ws.name workshop_name, t.task_order_id, ord.order_number AS task_order_number, a.name name, a.serial_number, a.specification, a.length, a.material, a.drawing_number, a.net_weight, a.gross_weight, a.total_net_weight, a.total_gross_weight, a.drawing_weight, a.quantity, a.bool_all_part_send_directly boolAllPartSendDirectly, a.surface_area / 1000000 surface_area, t.task_quantity, t.complete_quantity AS warehouse_quantity, t.print_quantity, t.print_time, t.ask_complete_time, t.bool_one_code 'boolOneCode', p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name', batch.`id` 'areaBatch.id', batch.`name` 'areaBatch.name', line.name AS productionLineName FROM mes_building_task t INNER JOIN tech_artifact a ON a.id = t.product_id and a.bool_abnormal_enum = 0 left join contract_project p on p.id = a.project_id left join plan_monomer m on m.id = a.monomer_id left join plan_area d on d.id = a.area_id left join plan_area_batch batch on batch.id = a.area_batch_id LEFT JOIN mes_building_task_order ord on t.task_order_id = ord.id LEFT JOIN mes_building_workshop ws on t.workshop_id = ws.id LEFT JOIN mes_building_production_line line on t.production_line_id = line.id WHERE t.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and t.bool_delete_enum = 0 AND a.bool_all_part_send_directly = 0
AND t.production_line_id = #{productionLineId}
AND t.project_id = #{projectId}
AND t.monomer_id = #{monomerId}
AND t.area_id = #{areaId}
AND a.name LIKE CONCAT('%',#{name},'%')
AND a.area_batch_id = #{areaBatchId}
AND a.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND a.specification LIKE CONCAT('%',#{specification},'%')
AND a.material LIKE CONCAT('%',#{material},'%')
AND t.status = #{status}
AND t.technology_status = #{technologyStatus}
AND t.complete_quantity = 0
AND (t.complete_quantity > 0 and t.complete_quantity < t.task_quantity)
AND t.complete_quantity = t.task_quantity
AND t.id in
#{taskId}
AND ( SELECT IFNULL(SUM(wr.quantity), 0) FROM mes_building_complete c INNER JOIN mes_building_warehouse_record wr ON wr.complete_id = c.id AND wr.type = 1 AND wr.status != 1 AND wr.bool_delete_enum = 0 WHERE c.task_id = t.id AND c.bool_delete_enum = 0 ) = 0
AND ( SELECT IFNULL(SUM(wr.quantity), 0) FROM mes_building_complete c INNER JOIN mes_building_warehouse_record wr ON wr.complete_id = c.id AND wr.type = 1 AND wr.status != 1 AND wr.bool_delete_enum = 0 WHERE c.task_id = t.id AND c.bool_delete_enum = 0 ) > 0 AND ( SELECT IFNULL(SUM(wr.quantity), 0) FROM mes_building_complete c INNER JOIN mes_building_warehouse_record wr ON wr.complete_id = c.id AND wr.type = 1 AND wr.status != 1 AND wr.bool_delete_enum = 0 WHERE c.task_id = t.id AND c.bool_delete_enum = 0 ) < t.task_quantity
AND ( SELECT IFNULL(SUM(wr.quantity), 0) FROM mes_building_complete c INNER JOIN mes_building_warehouse_record wr ON wr.complete_id = c.id AND wr.type = 1 AND wr.status != 1 AND wr.bool_delete_enum = 0 WHERE c.task_id = t.id AND c.bool_delete_enum = 0 ) >= t.task_quantity

SELECT DISTINCT steel_spec FROM mes_building_task a RIGHT JOIN tech_machine_part b ON a.product_id = b.id AND a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@MACHINE_PART.getType()}
a.bool_delete_enum=FALSE AND b.bool_delete_enum=FALSE and steel_spec IS NOT NULL AND steel_spec not like '%*%'
AND in_production_quantity=0
AND complete_quantity>0 and complete_quantity<b.quantity
AND complete_quantity=b.quantity
AND b.project_id = #{projectId}
AND b.monomer_id = #{monomerId}
AND b.area_id = #{areaId}
AND a.factory_id = #{factoryId}
AND b.serial_number like '%'#{serialNumber}'%'
AND b.category =#{category}
AND a.product_process_id IN
#(productProcessId)

SELECT IFNULL(SUM(in_production_quantity), 0)
FROM mes_building_task
WHERE bool_delete_enum = 0
  AND product_id = #{productId}
  AND task_type_enum = #{productType}

SELECT a.id 'area.id', a.name 'area.name', a.product_type 'area.product_type', IFNULL( quantity, 0 ) quantity, IFNULL( mete, 0 ) mete, IFNULL( complete_quantity, 0 ) complete_quantity, IFNULL( complete_mete, 0 ) complete_mete FROM plan_area a LEFT JOIN ( SELECT a.area_id, IFNULL(sum(a.quantity),0) quantity,
IFNULL(sum(a.quantity*a.net_weight),0) IFNULL(sum(a.quantity*a.length),0) mete, IFNULL(sum(a.complete_quantity),0) complete_quantity,
IFNULL(sum(a.complete_quantity*a.net_weight),0) IFNULL(sum(a.complete_quantity*a.length),0) complete_mete FROM ( SELECT product.*, complete.* FROM
tech_artifact tech_enclosure product LEFT JOIN ( SELECT product_id, sum( quantity ) complete_quantity FROM mes_building_complete
task_type_enum = #{productType}
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
GROUP BY product_id ) AS complete ON complete.product_id = product.id
product.bool_delete_enum = 0
AND product.project_id=#{projectId}
AND product.monomer_id=#{monomerId}
AND product.bool_delete_enum=0
) AS a GROUP BY a.area_id) AS b ON a.id=b.area_id WHERE
a.product_type =1 a.product_type !=1
AND a.bool_delete_enum = 0 AND project_id = #{projectId} AND monomer_id = #{monomerId}

SELECT mw.id workShopId, mw.NAME workShopName, pl.id id, pl.`name` name, a.task_type_enum taskType, a.start_dateate startDate, a.end_date endDate, a.task_quantity taskQuantity, a.task_net_weight, a.task_gross_weight, a.complete_quantity completeQuantity, a.complete_net_weight, a.complete_gross_weight, (a.complete_quantity/a.task_quantity) rate FROM ( SELECT a.production_line_id, a.workshop_id, a.task_type_enum, DATE(#{startTime}) start_dateate, DATE(#{endTime}) end_date, IFNULL(SUM( a.task_quantity ),0) task_quantity, IFNULL(SUM( a.complete_quantity ),0) complete_quantity, IFNULL(SUM( a.complete_quantity * ta.net_weight ),0) complete_net_weight, IFNULL(SUM( a.complete_quantity * ta.gross_weight ),0) complete_gross_weight, IFNULL(SUM( a.task_quantity * ta.net_weight ),0) task_net_weight, IFNULL(SUM( a.task_quantity * ta.gross_weight ),0) task_gross_weight FROM mes_building_task a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
LEFT JOIN tech_machine_part ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
WHERE a.bool_delete_enum = FALSE AND a.task_type_enum=#{taskType}
AND a.project_id=#{projectId}
AND a.workshop_id=#{workShopId}
and DATE(a.create_time) >= DATE(#{startTime})
and DATE(a.create_time) <= DATE(#{endTime})
GROUP BY a.production_line_id, a.workshop_id, a.task_type_enum ) a LEFT JOIN mes_building_workshop mw ON mw.id = a.workshop_id AND mw.bool_delete_enum = FALSE AND mw.bool_enabled_enum =TRUE LEFT JOIN mes_building_production_line pl ON a.production_line_id = pl.id AND pl.bool_delete_enum = FALSE AND pl.bool_enabled_enum = TRUE

SELECT a.workShopId workShopId, a.workShopName workShopName, a.id id, a.`NAME` NAME, sum( a.taskQuantity ) taskQuantity, sum( a.task_net_weight ) task_net_weight, sum( a.task_gross_weight ) task_gross_weight, sum( a.completeQuantity ) completeQuantity, sum( a.complete_net_weight ) complete_net_weight, sum( a.complete_gross_weight ) complete_gross_weight, a.task_type_enum taskType FROM ( SELECT a.workShopId workShopId, a.workShopName workShopName, a.id id, a.`NAME` NAME, a.taskQuantity taskQuantity, a.task_net_weight task_net_weight, a.task_gross_weight task_gross_weight, a.completeQuantity completeQuantity, a.complete_net_weight complete_net_weight, a.complete_gross_weight complete_gross_weight, CASE a.task_type_enum WHEN 16 THEN 16 ELSE 16 END task_type_enum FROM ( SELECT mw.id workShopId, mw.NAME workShopName, pl.id id, pl.`name` NAME, a.task_type_enum task_type_enum, a.task_quantity taskQuantity, a.task_net_weight task_net_weight, a.task_gross_weight task_gross_weight, a.complete_quantity completeQuantity, a.complete_net_weight complete_net_weight, a.complete_gross_weight complete_gross_weight FROM ( SELECT a.production_line_id, a.workshop_id, a.task_type_enum, IFNULL( SUM( a.task_quantity ), 0 ) task_quantity, IFNULL( SUM( a.complete_quantity ), 0 ) complete_quantity, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) END task_net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) END task_gross_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) END complete_net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) END complete_gross_weight FROM mes_building_task a LEFT JOIN tech_assemble ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE WHERE a.bool_delete_enum = FALSE AND a.task_type_enum & 16
AND a.project_id=#{projectId}
AND a.workshop_id=#{workShopId}
and DATE(a.create_time) >= DATE(#{startTime})
and DATE(a.create_time) <= DATE(#{endTime})
GROUP BY a.production_line_id, a.workshop_id, a.task_type_enum ) a LEFT JOIN mes_building_workshop mw ON mw.id = a.workshop_id AND mw.bool_delete_enum = FALSE AND mw.bool_enabled_enum = TRUE LEFT JOIN mes_building_production_line pl ON a.production_line_id = pl.id AND pl.bool_delete_enum = FALSE AND pl.bool_enabled_enum = TRUE ) a ) a GROUP BY a.workShopId, a.workShopName, a.id, a.`NAME`, a.task_type_enum

SELECT DATE_FORMAT( a.create_time, '%Y-%m' ) month, sum(a.task_quantity) quantity, IFNULL(sum(a.task_quantity*ta.net_weight),0) net_weight, IFNULL(sum(a.task_quantity*ta.gross_weight),0) gross_weight, sum(a.complete_quantity) completeQuantity, IFNULL( sum( a.complete_quantity * ta.gross_weight ), 0) complete_gross_weight, IFNULL( sum( a.complete_quantity * ta.net_weight ), 0) complete_net_weight FROM mes_building_task a LEFT JOIN tech_artifact ta on ta.id=a.product_id AND ta.bool_delete_enum=false WHERE a.bool_delete_enum = false AND a.task_type_enum=2
AND DATE_FORMAT( a.create_time, '%Y')= DATE_FORMAT( #{dateTime}, '%Y' )
AND a.workshop_id = #{workShopId}
AND a.production_line_id = #{productionLineId}
GROUP BY DATE_FORMAT( a.create_time, '%Y-%m' )

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', pl.id 'monomer.id', pl.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.quantity, a.net_weight, a.gross_weight, a.complete_quantity, a.complete_net_weight, a.complete_gross_weight FROM ( SELECT a.project_id, a.monomer_id, a.area_id, SUM( a.task_quantity ) quantity, IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) net_weight, IFNULL( SUM( a.task_quantity * ta.gross_weight ), 0 ) gross_weight, SUM( a.complete_quantity ) complete_quantity, IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( a.complete_quantity * ta.gross_weight ), 0 ) complete_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = false WHERE a.bool_delete_enum = false AND a.task_type_enum=2
AND DATE_FORMAT( a.create_time, '%Y/%m')= DATE_FORMAT( #{dateTime}, '%Y/%m' )
AND a.workshop_id = #{workShopId}
AND a.production_line_id = #{productionLineId}
GROUP BY a.project_id, a.monomer_id, a.area_id ) a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pl ON pl.id=a.monomer_id LEFT JOIN plan_area pa ON pa.id=a.area_id

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', pl.id 'monomer.id', pl.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', workshop.id 'workshop.id', workshop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', a.serial_number, a.specification, a.material, a.length, a.net_weight, a.gross_weight, a.quantity, a.task_net_weight, a.task_gross_weight, a.complete_quantity, a.complete_net_weight, a.complete_gross_weight FROM ( SELECT a.project_id, a.monomer_id, a.area_id, a.workshop_id, a.production_line_id, ta.serial_number, ta.specification, ta.material, ta.length, ta.net_weight, ta.gross_weight, sum( a.task_quantity ) quantity, IFNULL( sum( a.task_quantity * ta.net_weight ), 0 ) task_net_weight, IFNULL( sum( a.task_quantity * ta.gross_weight ), 0 ) task_gross_weight, sum( a.complete_quantity ) complete_quantity, IFNULL( sum( a.complete_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( sum( a.complete_quantity * ta.gross_weight ), 0 ) complete_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE WHERE a.bool_delete_enum = FALSE AND a.task_type_enum=2
AND DATE_FORMAT( a.create_time, '%Y/%m')= DATE_FORMAT( #{dateTime}, '%Y/%m' )
AND a.workshop_id = #{workShopId}
AND a.production_line_id = #{productionLineId}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND ta.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.project_id, a.monomer_id, a.area_id, a.workshop_id, a.production_line_id, ta.id ) a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pl ON pl.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN mes_building_workshop workshop ON workshop.id = a.workshop_id LEFT JOIN mes_building_production_line line ON line.id = a.production_line_id ORDER BY a.complete_quantity ASC

SELECT mp.id 'workshop.id', mp.`name` 'workshop.name', ml.id 'productionLine.id', ml.`name` 'productionLine.name', b.NAME groupName,
ta.serial_number serialNumber, ta.net_weight, ta.gross_weight,
CASE a.task_type_enum WHEN 16 THEN ta.serial_number END serial_number, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END net_weight, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END gross_weight,
a.task_quantity quantity, a.inspection_quantity completeQuantity FROM mes_building_task_process a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id
LEFT JOIN tech_machine_part ta ON ta.id = a.product_id
LEFT JOIN tech_assemble ta ON ta.id = a.product_id
LEFT JOIN mes_building_groups b ON b.id = a.groups_id LEFT JOIN mes_building_workshop mp ON mp.id = b.workshop_id LEFT JOIN mes_building_production_line ml ON ml.id = b.production_line_id WHERE a.bool_delete_enum = 0
AND a.task_type_enum = #{taskType}
AND a.task_type_enum & 16
AND a.project_id = #{projectId}
AND a.process_id = #{processId}
AND a.production_line_id = #{productionLineId}
AND a.product_id=#{productId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND date(a.create_time) >= date(#{startDate})
AND date(a.create_time) <= date(#{endDate})

SELECT pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.id, a.`name`, a.serial_number, a.material, a.specification, a.length, a.net_weight, a.gross_weight, a.task_quantity quantity, a.total_net_weight, a.total_gross_weight, a.complete_quantity, a.complete_net_weight, a.complete_gross_weight, CASE WHEN a.task_quantity > a.complete_quantity THEN 0 WHEN a.task_quantity = a.complete_quantity THEN 1 END status FROM ( SELECT a.monomer_id, a.area_id, ta.id, ta.`name`, ta.serial_number, ta.material, ta.specification, ta.length, ta.net_weight, ta.gross_weight, IFNULL( SUM( a.task_quantity ), 0 ) task_quantity, IFNULL( SUM( a.complete_quantity ), 0 ) complete_quantity, IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) total_net_weight, IFNULL( SUM( a.task_quantity * ta.gross_weight ), 0 ) total_gross_weight, IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( a.complete_quantity * ta.gross_weight ), 0 ) complete_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id WHERE a.bool_delete_enum = 0
AND a.workshop_id = #{workshopId}
AND a.task_type_enum = 2 AND a.project_id = #{projectId} AND a.monomer_id = #{monomerId} AND a.area_id = #{areaId} GROUP BY a.monomer_id, a.area_id, ta.id ) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id ORDER BY a.complete_quantity ASC

select IFNULL( SUM( a.task_quantity ), 0 ) quantity, IFNULL( SUM( a.task_net_weight ), 0 ) net_weight, IFNULL( SUM( a.task_gross_weight), 0 ) gross_weight from (SELECT IFNULL( SUM( a.task_quantity ), 0 ) task_quantity, IFNULL( SUM( a.task_quantity * artifact.net_weight ), 0 ) task_net_weight, IFNULL( SUM( a.task_quantity * artifact.gross_weight ), 0 ) task_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.project_id = #{projectId}
AND a.workshop_id = #{workshopId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate}) )a

select a.project_id, IFNULL( SUM( a.task_quantity ), 0 ) quantity, IFNULL( SUM( a.task_net_weight ), 0 ) net_weight, IFNULL( SUM( a.task_gross_weight), 0 ) gross_weight from (SELECT a.project_id, IFNULL( SUM( a.task_quantity ), 0 ) task_quantity, IFNULL( SUM( a.task_quantity * artifact.net_weight ), 0 ) task_net_weight, IFNULL( SUM( a.task_quantity * artifact.gross_weight ), 0 ) task_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.project_id in
#{projectId}
AND a.workshop_id = #{workshopId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
group by a.project_id )a group by a.project_id

SELECT pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.create_time completeTime, a.quantity, a.name, a.serial_number, a.specification, a.material, a.net_weight, a.gross_weight, a.total_net_weight, a.total_gross_weight FROM ( SELECT a.monomer_id, a.area_id, SUM( a.task_quantity) quantity , a.create_time, artifact.`name` name, artifact.serial_number, artifact.specification, artifact.material, IFNULL( SUM( artifact.net_weight ), 0 ) net_weight, IFNULL( SUM( artifact.gross_weight ), 0 ) gross_weight, IFNULL( SUM( a.task_quantity * artifact.net_weight ), 0 ) total_net_weight, IFNULL( SUM( a.task_quantity * artifact.gross_weight ), 0 ) total_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.project_id = #{projectId}
AND a.workshop_id = #{workshopId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND artifact.serial_number like CONCAT('%',#{serialNumber},'%')
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
GROUP BY a.monomer_id, a.area_id, a.create_time, artifact.id ) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id

SELECT IFNULL( SUM( a.task_quantity * ta.net_weight)/12, 0 ) yearAvgNetWeight, IFNULL( SUM(a.task_quantity * ta.net_weight), 0 ) taskNetWeight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.workshop_id = #{workshopId}
AND DATE_FORMAT(a.create_time, '%Y') = DATE_FORMAT(NOW(), '%Y')

SELECT task.*, CASE task.task_type_enum WHEN 16 THEN ass.bool_all_part_send_directly ELSE par.bool_all_part_send_directly END boolAllPartSendDirectly, CASE task.task_type_enum WHEN 16 THEN ass.bool_send_directly ELSE par.bool_send_directly END boolSendDirectly FROM mes_building_task task LEFT JOIN tech_assemble ass ON task.product_id = ass.id LEFT JOIN tech_machine_part par ON par.id = task.product_id WHERE task.bool_delete_enum = 0
AND task.project_id = #{projectId}
AND task.monomer_id = #{monomerId}
AND task.area_id = #{areaId}
AND task.area_batch_id = #{areaBatchId}
AND task.task_type_enum & #{productType}

SELECT IFNULL( a.project_id, b.project_id ) project_id, IFNULL( a.monomer_id, b.monomer_id ) monomer_id, IFNULL( a.mon, b.mon ) date, IFNULL( a.scheduling_total_gross_weight, 0 )scheduling_total_gross_weight, IFNULL( a.scheduling_total_net_weight, 0 )scheduling_total_net_weight, IFNULL( b.complete_total_net_weight, 0 )complete_total_net_weight, IFNULL( b.complete_total_gross_weight , 0 )complete_total_gross_weight FROM ( SELECT task.project_id, task.monomer_id, DATE_FORMAT ( task.create_time, '%Y-%m-%d' ) mon, IFNULL( SUM( task.task_quantity * ta.net_weight ), 0 ) scheduling_total_net_weight, IFNULL( SUM( task.task_quantity * ta.gross_weight ), 0 ) scheduling_total_gross_weight FROM mes_building_task task LEFT JOIN tech_artifact ta ON ta.id = task.product_id WHERE task.bool_delete_enum = 0 AND task.task_type_enum = 2
AND DATE_FORMAT( task.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND task.workshop_id = #{workshopId}
AND task.project_id IN
#{projectId}
GROUP BY task.project_id, task.monomer_id, mon ) a RIGHT JOIN ( SELECT c.project_id, c.monomer_id, DATE_FORMAT ( c.create_time, '%Y-%m-%d' ) mon, IFNULL( SUM( c.quantity * ta.net_weight ), 0 ) complete_total_net_weight, IFNULL( SUM( c.quantity * ta.gross_weight ), 0 ) complete_total_gross_weight FROM mes_building_complete c LEFT JOIN tech_artifact ta ON ta.id = c.product_id WHERE c.bool_delete_enum = 0 AND c.task_type_enum = 2
AND DATE_FORMAT( c.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND c.workshop_id = #{workshopId}
AND c.project_id IN
#{projectId}
GROUP BY c.project_id, c.monomer_id, mon ) b ON a.monomer_id = b.monomer_id AND a.mon = b.mon
UNION
SELECT IFNULL( a.project_id, b.project_id ) project_id, IFNULL( a.monomer_id, b.monomer_id ) monomer_id, IFNULL( a.mon, b.mon ) m, IFNULL( a.scheduling_total_gross_weight, 0 )scheduling_total_gross_weight, IFNULL( a.scheduling_total_net_weight, 0 )scheduling_total_net_weight, IFNULL( b.complete_total_net_weight, 0 )complete_total_net_weight, IFNULL( b.complete_total_gross_weight , 0 )complete_total_gross_weight FROM ( SELECT task.project_id, task.monomer_id, DATE_FORMAT ( task.create_time, '%Y-%m-%d' ) mon, IFNULL( SUM( task.task_quantity * ta.net_weight ), 0 ) scheduling_total_net_weight, IFNULL( SUM( task.task_quantity * ta.gross_weight ), 0 ) scheduling_total_gross_weight FROM mes_building_task task LEFT JOIN tech_artifact ta ON ta.id = task.product_id WHERE task.bool_delete_enum = 0 AND task.task_type_enum = 2
AND DATE_FORMAT( task.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND task.workshop_id = #{workshopId}
AND task.project_id IN
#{projectId}
GROUP BY task.project_id, task.monomer_id, mon ) a LEFT JOIN ( SELECT c.project_id, c.monomer_id, DATE_FORMAT ( c.create_time, '%Y-%m-%d' ) mon, IFNULL( SUM( c.quantity * ta.net_weight ), 0 ) complete_total_net_weight, IFNULL( SUM( c.quantity * ta.gross_weight ), 0 ) complete_total_gross_weight FROM mes_building_complete c LEFT JOIN tech_artifact ta ON ta.id = c.product_id WHERE c.bool_delete_enum = 0 AND c.task_type_enum = 2
AND DATE_FORMAT( c.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND c.workshop_id = #{workshopId}
AND c.project_id IN
#{projectId}
GROUP BY c.project_id, c.monomer_id, mon ) b ON a.monomer_id = b.monomer_id AND a.mon = b.mon

SELECT a.date date, a.total_net_weight, a.total_gross_weight, a.complete_net_weight, a.complete_gross_weight FROM (SELECT MONTH(task.create_time) date, IFNULL( SUM( task.task_quantity ), 0 ) quantity, IFNULL( SUM( task.task_quantity * product.net_weight ), 0 ) total_net_weight, IFNULL( SUM( task.task_quantity * product.gross_weight ), 0 ) total_gross_weight FROM mes_building_task task LEFT JOIN tech_artifact product ON product.id = task.product_id WHERE task.bool_delete_enum = 0 AND task.task_type_enum=2
AND DATE_FORMAT( task.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND task.workshop_id = #{workshopId}
AND task.project_id=#{projectId}
AND task.monomer_id=#{monomerId}
GROUP BY MONTH(task.create_time))task
UNION ALL
(SELECT MONTH(complete.create_time) date, IFNULL( SUM( complete.quantity ), 0 ) quantity, IFNULL( SUM( complete.quantity * product.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( complete.quantity * product.gross_weight ), 0 ) complete_gross_weight FROM mes_building_complete complete LEFT JOIN tech_artifact product ON product.id = complete.product_id WHERE complete.bool_delete_enum = 0 AND complete.task_type_enum=2
AND DATE_FORMAT( complete.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND complete.workshop_id = #{workshopId}
AND complete.project_id=#{projectId}
AND complete.monomer_id=#{monomerId}
GROUP BY MONTH(complete.create_time) )complete )a

SELECT a.project_id 'project.id', cp.`name` 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.serialNumber', a.monomer_id 'monomer.id', pl.`name` 'monomer.name', a.area_id 'area.id', pa.`name` 'area.name', a.id productId, a.`name`, a.serial_number, a.specification, a.material, a.length, a.scheduling_quantity, a.scheduling_total_net_weight, a.scheduling_total_gross_weight, a.complete_quantity, a.complete_total_net_weight, a.complete_total_gross_weight, CASE WHEN a.scheduling_quantity>a.complete_quantity THEN 1 WHEN a.scheduling_quantity=a.complete_quantity THEN 2 END sort FROM ( SELECT task.project_id, task.monomer_id, task.area_id, ta.id, ta.`name`, ta.serial_number, ta.specification, ta.material, ta.length, IFNULL( SUM( task.task_quantity ), 0 ) scheduling_quantity, IFNULL( SUM( task.task_quantity * ta.net_weight ), 0 ) scheduling_total_net_weight, IFNULL( SUM( task.task_quantity * ta.gross_weight ), 0 ) scheduling_total_gross_weight, IFNULL( SUM( task.complete_quantity ), 0 ) complete_quantity, IFNULL( SUM( task.complete_quantity * ta.net_weight ), 0 ) complete_total_net_weight, IFNULL( SUM( task.complete_quantity * ta.gross_weight ), 0 ) complete_total_gross_weight FROM mes_building_task task LEFT JOIN tech_artifact ta ON ta.id = task.product_id WHERE task.bool_delete_enum = 0 AND task.task_type_enum=2
AND DATE_FORMAT( task.create_time, '%Y/%m' )= DATE_FORMAT( #{dateTime}, '%Y/%m' )
AND task.workshop_id = #{workshopId}
AND task.project_id = #{projectId}
AND task.monomer_id = #{monomerId}
AND task.area_id = #{areaId}
AND ta.serial_number like CONCAT('%',#{serialNumber},'%')
GROUP BY task.project_id, task.monomer_id, task.area_id, ta.id ) a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pl ON pl.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id ORDER BY sort ASC,a.complete_quantity ASC

SELECT #{startDate} '/' #{endDate} date, IFNULL( SUM( s.task_quantity ), 0 ) quantity, IFNULL( SUM( s.task_quantity * product.net_weight ), 0 ) total_net_weight, IFNULL( SUM( s.task_quantity * product.gross_weight ), 0 ) total_gross_weight FROM mes_building_task s LEFT JOIN tech_artifact product ON product.id = s.product_id WHERE s.bool_delete_enum = 0 AND s.task_type_enum = 2
AND DATE_FORMAT( s.create_time, '%Y/%m/%d' ) >= DATE_FORMAT( #{startDate}, '%Y/%m/%d' )
AND DATE_FORMAT( s.create_time, '%Y/%m/%d' ) <= DATE_FORMAT( #{endDate}, '%Y/%m/%d' )
AND s.workshop_id = #{workshopId}
AND s.project_id=#{projectId}
AND s.monomer_id=#{monomerId}

select IFNULL( SUM( a.task_quantity ), 0 ) quantity, IFNULL( SUM( a.task_net_weight ), 0 ) net_weight, IFNULL( SUM( a.task_gross_weight), 0 ) gross_weight from (SELECT IFNULL( SUM( a.task_quantity-a.complete_quantity ), 0 ) task_quantity, IFNULL( SUM( ( a.task_quantity-a.complete_quantity ) * artifact.net_weight ), 0 ) task_net_weight, IFNULL( SUM( ( a.task_quantity-a.complete_quantity ) * artifact.gross_weight ), 0 ) task_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.project_id = #{projectId}
AND a.workshop_id = #{workshopId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
AND a.product_id IN
#{singleArtifactId}
)a

SELECT wp.id 'workshop.id', wp.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', pl.id 'monomer.id', pl.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.id, a.serial_number, a.specification, a.material, a.length, a.net_weight, a.gross_weight, CASE WHEN a.task_quantity > a.complete_quantity THEN 1 WHEN a.task_quantity = a.complete_quantity THEN 2 END status, a.task_quantity quantity, a.task_net_weight, a.task_gross_weight, a.complete_quantity, a.complete_net_weight, a.complete_gross_weight FROM ( SELECT a.workshop_id, a.production_line_id, a.groups_id, a.monomer_id, a.area_id, SUM( a.task_quantity ) task_quantity, SUM( a.complete_quantity ) complete_quantity, ta.id, ta.serial_number, ta.specification, ta.material, ta.length, ta.net_weight, ta.gross_weight, IFNULL(SUM( a.task_quantity * ta.net_weight),0) task_net_weight, IFNULL(SUM( a.task_quantity * ta.gross_weight),0) task_gross_weight, IFNULL(SUM( a.complete_quantity * ta.net_weight),0) complete_net_weight, IFNULL(SUM( a.complete_quantity * ta.gross_weight),0) complete_gross_weight FROM mes_building_task a
LEFT JOIN tech_artifact ta ON a.product_id=ta.id
a.bool_delete_enum = 0 AND a.task_type_enum = #{taskType}
AND ta.serial_number like CONCAT('%',#{serialNumber},'%')
AND date(a.create_time) >= date(#{startDate})
AND date(a.create_time) <= date(#{endDate})
AND a.task_quantity > a.complete_quantity
AND a.task_quantity = a.complete_quantity
AND a.project_id=#{projectId}
AND a.production_line_id = #{productionLineId}
AND a.workshop_id = #{workshopId}
AND a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
AND a.product_id IN
#{singleArtifactId}
GROUP BY a.workshop_id, a.production_line_id, a.groups_id, a.monomer_id, a.area_id, ta.id ) a LEFT JOIN mes_building_workshop wp on wp.id=a.workshop_id LEFT JOIN mes_building_production_line line on line.id=a.production_line_id LEFT JOIN mes_building_groups gro ON gro.id=a.groups_id LEFT JOIN plan_monomer pl on pl.id=a.monomer_id LEFT JOIN plan_area pa ON pa.id=a.area_id ORDER BY status ASC,a.complete_quantity ASC

SELECT pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.quantity, a.serial_number, a.name, a.specification, a.material, a.net_weight, a.total_net_weight, a.gross_weight, a.total_gross_weight FROM ( SELECT a.monomer_id, a.area_id, ta.id, ta.`name`, ta.serial_number, ta.specification, ta.material, ta.net_weight, ta.gross_weight, IFNULL( SUM( a.task_quantity - a.complete_quantity ), 0 ) quantity, IFNULL( SUM( (a.task_quantity - a.complete_quantity) * ta.net_weight ), 0 ) total_net_weight, IFNULL( SUM( (a.task_quantity - a.complete_quantity) * ta.gross_weight ), 0 ) total_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum =2 AND a.project_id = #{projectId}
a.monomer_id= #{monomerId}
a.workshop_id= #{workshopId}
a.area_id= #{areaId}
AND a.product_id IN
#{singleArtifactId}
ta.serial_number like CONCAT('%',#{serialNumber},'%')
GROUP BY a.monomer_id, a.area_id, ta.id ) a LEFT JOIN plan_area pa ON a.area_id = pa.id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id WHERE a.quantity>0

SELECT t.factory_id, t.workshop_id, sum( t.task_quantity )task_quantity, sum( t.complete_quantity )warehouseQuantity, t.task_type_enum AS productType, a.id id, a.serial_number, a.specification, a.length, a.material, a.drawing_number, a.net_weight, a.total_net_weight, '零件-直发件' NAME, a.gross_weight, a.total_gross_weight, a.quantity, a.bool_all_part_send_directly, p.id 'project.id', p.NAME 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name', batch.`id` 'areaBatch.id', batch.`name` 'areaBatch.name' FROM mes_building_task t INNER JOIN tech_machine_part a ON a.id = t.product_id AND a.bool_send_directly = 1 AND a.bool_process = 1 LEFT JOIN contract_project p ON p.id = t.project_id LEFT JOIN plan_monomer m ON m.id = t.monomer_id LEFT JOIN plan_area d ON d.id = t.area_id LEFT JOIN plan_area_batch batch ON batch.id = t.area_batch_id WHERE t.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@MACHINE_PART.getType()} and t.bool_delete_enum = 0 and a.relation_type!=18
AND t.production_line_id = #{productionLineId}
AND t.project_id = #{projectId}
AND t.monomer_id = #{monomerId}
AND t.area_id = #{areaId}
AND a.name LIKE CONCAT('%',#{name},'%')
AND a.area_batch_id = #{areaBatchId}
AND a.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND a.specification LIKE CONCAT('%',#{specification},'%')
AND a.material LIKE CONCAT('%',#{material},'%')
AND t.status = #{status}
AND t.technology_status = #{technologyStatus}
AND t.complete_quantity = 0
AND (t.complete_quantity > 0 and t.complete_quantity < t.task_quantity)
AND t.complete_quantity = t.task_quantity
GROUP BY t.project_id, t.monomer_id, t.area_id, t.area_batch_id, t.product_id, t.factory_id, t.workshop_id

SELECT sum( t.task_quantity ) task_quantity, sum( t.complete_quantity ) warehouseQuantity, t.task_type_enum AS productType, t.factory_id, t.workshop_id, '部件-直发件' NAME, a.id id, a.serial_number, a.specification, a.length, a.material, a.drawing_number, a.net_weight, a.total_net_weight, 0 gross_weight, 0 total_gross_weight, a.quantity, a.bool_all_part_send_directly, p.id 'project.id', p.NAME 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name', batch.`id` 'areaBatch.id', batch.`name` 'areaBatch.name' FROM mes_building_task t INNER JOIN tech_assemble a ON a.id = t.product_id AND a.bool_send_directly = 1 and a.bool_process=1 LEFT JOIN contract_project p ON p.id = t.project_id LEFT JOIN plan_monomer m ON m.id = t.monomer_id LEFT JOIN plan_area d ON d.id = t.area_id LEFT JOIN plan_area_batch batch ON batch.id = t.area_batch_id WHERE t.task_type_enum =${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ASSEMBLE.getType()} and t.bool_delete_enum = 0
AND t.production_line_id = #{productionLineId}
AND t.project_id = #{projectId}
AND t.monomer_id = #{monomerId}
AND t.area_id = #{areaId}
AND a.name LIKE CONCAT('%',#{name},'%')
AND a.area_batch_id = #{areaBatchId}
AND a.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND a.specification LIKE CONCAT('%',#{specification},'%')
AND a.material LIKE CONCAT('%',#{material},'%')
AND t.status = #{status}
AND t.technology_status = #{technologyStatus}
AND t.complete_quantity = 0
AND (t.complete_quantity > 0 and t.complete_quantity < t.task_quantity)
AND t.complete_quantity = t.task_quantity
GROUP BY t.project_id, t.monomer_id, t.area_id, t.area_batch_id, t.product_id, t.factory_id, t.workshop_id

SELECT task.* FROM mes_building_task_order ord LEFT JOIN mes_building_task task ON ord.id = task.task_order_id AND task.bool_delete_enum = 0
LEFT JOIN tech_artifact product ON task.product_id = product.id AND product.bool_delete_enum =0
LEFT JOIN tech_assemble product ON task.product_id = product.id AND product.bool_delete_enum =0
LEFT JOIN tech_machine_part product ON task.product_id = product.id AND product.bool_delete_enum =0
WHERE 1=1
AND ord.id=#{taskOrderId}
AND task.area_id=#{areaId}
AND task.area_id=#{areaId}
AND product.serial_number like concat('%', #{serialNumber}, '%')
AND product.specification like concat('%', #{specification}, '%')

SELECT shop.`name` 'shopName', line.`name` 'lineName', IFNULL( sum( task.task_quantity ), 0 ) 'scheduledQuantity', ROUND( IFNULL( sum( task.task_quantity * ass.net_weight ), 0 )/ 1000, 3 ) 'scheduledWeight', sum(ass.quantity - IFNULL( task.task_quantity, 0 )) 'unScheduledQuantity', ROUND( sum(( ass.quantity - IFNULL( task.task_quantity, 0 )) * ass.net_weight )/ 1000, 3 ) 'unScheduledWeight', sum( task.complete_quantity ) 'completeQuantity', ROUND( sum( task.complete_quantity * ass.net_weight )/ 1000, 3 ) 'completeWeight' FROM tech_assemble ass INNER JOIN mes_building_task task ON task.product_id = ass.id AND task.bool_delete_enum = 0 and task.task_type_enum = 16 LEFT JOIN mes_building_workshop shop ON task.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON task.production_line_id = line.id AND line.bool_delete_enum = 0 WHERE ass.bool_delete_enum = 0
and shop.workshop_id = #{workshopId}
and ass.project_id = #{projectId}
GROUP BY shop.`name`, line.`name`

SELECT shop.id workshopId, shop.name workshopName, prss.id processId, prss.name processName, tulink.team_id teamId, tulink.user_name teamLeaderName, DATE_FORMAT( rep.create_time, '%Y-%m' ) date, CASE rep.task_type_enum when 1 then IFNULL( sum( rep.quantity * part.net_weight ), 0 ) when 2 then IFNULL( sum( rep.quantity * art.net_weight ), 0 ) when 16 then IFNULL( sum( rep.quantity * ass.net_weight ), 0 ) end as totalCompleteWeight FROM mes_building_produce_team_report rep INNER JOIN mes_building_team_user_link tulink ON rep.team_id = tulink.team_id AND tulink.bool_leader_enum = 1 AND tulink.bool_delete_enum = 0 left join mes_building_production_line line on rep.production_line_id = line.id AND line.bool_delete_enum = 0 left join mes_building_workshop shop on line.workshop_id = shop.id AND shop.bool_delete_enum = 0 left join mes_building_process prss on rep.process_id = prss.id AND prss.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON rep.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN tech_assemble ass on rep.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN tech_machine_part part ON part.id = rep.product_id and part.bool_delete_enum = 0 WHERE rep.bool_delete_enum = 0 AND rep.bool_delete_enum = 0 AND DATE_FORMAT( rep.create_time, '%Y' ) = DATE_FORMAT(#{time}, '%Y' )
and rep.team_id in
#{teamId}
and ( ( rep.task_type_enum = 2 and art.project_id in
#{projectId}
) or ( rep.task_type_enum = 16 and ass.project_id in
#{projectId}
) or ( rep.task_type_enum = 1 and part.project_id in
#{projectId}
) )
GROUP BY shop.id, prss.id, tulink.team_id, tulink.user_name, DATE_FORMAT( rep.create_time, '%Y-%m'), rep.task_type_enum

SELECT cp.serial_number, cp.short_name, sum( task.task_quantity ) taskQuantity, sum( task.task_quantity * art.net_weight ) taskWeightSum FROM mes_building_task task LEFT JOIN tech_artifact art ON task.product_id = art.id and art.bool_delete_enum = 0 left join contract_project cp on art.project_id = cp.id and cp.bool_delete_enum = 0 WHERE task.bool_delete_enum = 0 AND task.task_type_enum = 2 and DATE_FORMAT(task.create_time,'%Y-%m') = DATE_FORMAT(#{date},'%Y-%m')
and task.workshop_id = #{workshopId}
GROUP BY cp.serial_number, cp.short_name

SELECT cp.serial_number, cp.short_name, IFNULL( sum( pro.task_quantity), 0 ) taskQuantity, IFNULL( sum( pro.task_quantity * art.net_weight ), 0 ) taskWeightSum, IFNULL( sum( pro.quantity), 0 ) completeQuantity, IFNULL( sum( rep.quantity * art.net_weight ), 0 ) completeWeightSum FROM mes_building_task_process pro INNER JOIN mes_building_team_user_link tulink ON pro.team_id = tulink.team_id AND tulink.bool_leader_enum = 1 LEFT JOIN tech_artifact art ON pro.product_id = art.id LEFT JOIN contract_project cp on art.project_id = cp.id and cp.bool_delete_enum = 0 LEFT JOIN mes_building_produce_team_report rep ON pro.task_id = rep.task_id WHERE pro.bool_delete_enum = 0 AND tulink.bool_delete_enum = 0 AND art.bool_delete_enum = 0 AND rep.bool_delete_enum = 0 AND pro.task_type_enum = 2 and DATE_FORMAT(task.create_time,'%Y-%m') = DATE_FORMAT(#{date},'%Y-%m')
and pro.team_id = #{teamId}
GROUP BY cp.serial_number, cp.short_name

SELECT art.`name`, art.serial_number, art.specification, art.length, art.material, sum(task.task_quantity) quantity, sum(task.complete_quantity) producedQuantity, tulink.user_name teamLeaderName FROM mes_building_task task LEFT JOIN tech_artifact art ON task.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN mes_building_task_process pro ON task.id = pro.task_id AND pro.sequence = 0 and pro.bool_delete_enum = 0 LEFT JOIN mes_building_team_user_link tulink ON pro.team_id = tulink.team_id AND tulink.bool_leader_enum = 1 WHERE task.bool_delete_enum = 0 and tulink.bool_delete_enum = 0 AND task.task_type_enum = 2
and task.product_id = #{productId}
GROUP BY art.id,tulink.user_name

SELECT task.id AS taskId, task.product_id, product.name, product.serial_number, product.specification, product.material, ROUND(product.surface_area / 1000000,4) surface_area, product.net_weight, work.name workshopName, task.task_quantity, product.net_weight, task.complete_quantity, task.create_time AS schedulingTime FROM mes_building_task task LEFT JOIN tech_artifact product on product.id = task.product_id and product.bool_delete_enum = 0 left join mes_building_workshop work on task.workshop_id = work.id and work.bool_delete_enum = 0 where task.bool_delete_enum = 0 and task.project_id = #{projectId} and task.task_type_enum = 2
AND product.serial_number like concat('%', #{serialNumber}, '%')
and task.workshop_id = #{workShopId}
and task.production_line_id = #{productionLineId}
and task.classification_id = #{classId}
and task.monomer_id = #{monomerId}
and task.area_id in
#{areaId}
and task.product_id in
#{artifactId}
and task.complete_quantity != task.task_quantity
and (task.complete_quantity > 0 and task.complete_quantity < task.task_quantity)
and task.complete_quantity = task.task_quantity
AND date_format(task.create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(task.create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
and task.area_batch_id in
#{areaBatchId}

SELECT task.id AS artifactTaskId, partTask.product_id, sum(ifnull(partTask.complete_quantity,0)) AS totalCompleteQuantity, part.net_weight FROM mes_building_task task LEFT JOIN mes_building_machine_part_scheduling_artifact_task_link link ON task.id = link.task_id and link.bool_delete_enum =0 LEFT JOIN mes_building_machine_part_scheduling_link slink ON link.scheduling_link_id = slink.id and slink.bool_delete_enum =0 LEFT JOIN mes_building_task partTask ON partTask.product_id = slink.product_id and partTask.bool_delete_enum =0 AND partTask.machine_part_scheduling_id = slink.scheduling_id left join tech_machine_part part on part.id = partTask.product_id and part.bool_delete_enum =0 WHERE task.bool_delete_enum = 0 and task.id in
#{taskId}
group by task.id,partTask.product_id

SELECT task.id artifactTaskId, GROUP_CONCAT(DISTINCT shop.`name` SEPARATOR ',') AS assistWorkShopNames FROM mes_building_task task Inner JOIN mes_building_assist ass ON task.id = ass.task_id AND ass.bool_delete_enum = 0 left join mes_building_production_line line on ass.production_line_id = line.id and line.bool_delete_enum = 0 left join mes_building_workshop shop on line.workshop_id = shop.id and shop.bool_delete_enum = 0 WHERE task.bool_delete_enum = 0 and ass.task_id is not null and task.id in
#{taskId}
GROUP BY task.id

SELECT task.id As taskId, task.product_id , workshop.id AS 'workShop.id', workshop.name AS 'workShop.name', line.id AS 'productionLine.id', line.name AS 'productionLine.name', monomer.id As 'monomer.id', monomer.name As 'monomer.name', area.id As 'area.id', area.name As 'area.name',
classification.classification_name As classificationName,
classification.name As classificationName,
product.name, product.serial_number, product.specification, product.length, product.material, product.net_weight, product.gross_weight, task.task_quantity, task.complete_quantity, task.create_time AS schedulingTime, task.ask_complete_time FROM mes_building_task task LEFT JOIN plan_monomer monomer on monomer.id = task.monomer_id LEFT JOIN plan_area area on area.id = task.area_id LEFT JOIN mes_building_workshop workshop on workshop.id = task.workshop_id LEFT JOIN mes_building_production_line line on line.id = task.production_line_id
LEFT JOIN sys_structure_classification classification on classification.id = task.classification_id LEFT JOIN tech_artifact product on product.id = task.product_id
LEFT JOIN sys_assemble_config classification on classification.id = task.classification_id LEFT JOIN tech_assemble product on product.id = task.product_id
where task.bool_delete_enum =0 and task.project_id = #{projectId} and task.task_type_enum = #{productType}
AND product.serial_number like concat('%', #{serialNumber}, '%')
and task.workshop_id = #{workShopId}
and task.production_line_id = #{productionLineId}
and task.classification_id = #{classId}
and task.monomer_id = #{monomerId}
and task.area_id in
#{areaId}
and task.complete_quantity = 0
and (task.complete_quantity > 0 and task.complete_quantity < task.task_quantity)
and task.complete_quantity = task.task_quantity
and task.area_batch_id in
#{areaBatchId}
order by task.complete_quantity

