SELECT 5 AS lossWorkProgressStatisticsEnum, #{taskTypeEnum} AS taskTypeEnum, ym_t.`year_month`, ROUND(mbcl_t.productMonthOutput,3) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( select a.newYear_month, sum(a.totalNetWeight) AS productMonthOutput from (
SELECT report.in_year_month_date AS newYear_month, sum( report.quantity * partLink.quantity * ifnull( part.net_weight, 0 )) / 1000 AS totalNetWeight FROM mes_building_task_process taskProcess LEFT JOIN contract_project cp ON cp.id = taskProcess.project_id LEFT JOIN mes_building_produce_team_report report ON report.task_process_id = taskProcess.id INNER JOIN mes_building_machine_part_scheduling_artifact_task_link taskLink ON taskLink.task_id = taskProcess.task_id LEFT JOIN mes_building_machine_part_scheduling_link schedulingLink ON schedulingLink.id = taskLink.scheduling_link_id LEFT JOIN mes_building_task mtask ON mtask.product_id = schedulingLink.product_id AND mtask.machine_part_scheduling_id = schedulingLink.scheduling_id AND mtask.task_type_enum = 1
LEFT JOIN tech_artifact_machine_part_link partLink ON partLink.artifact_id = report.product_id
LEFT JOIN tech_assemble_machine_part_link partLink ON partLink.assemble_id = report.product_id
AND report.task_type_enum = #{relationType} AND partLink.machine_part_id = schedulingLink.product_id LEFT JOIN tech_machine_part part ON part.id = partLink.machine_part_id LEFT JOIN mes_building_workshop partWorkshop ON mtask.workshop_id = partWorkshop.id LEFT JOIN mes_building_workshop useWorkshop ON report. workshop_id = useWorkshop.id WHERE taskProcess.sequence = 0 AND taskProcess.bool_delete_enum = 0 AND taskProcess.task_type_enum = #{relationType} AND taskProcess.complete_quantity > 0 AND mtask.workshop_id != report.workshop_id
AND taskProcess.project_id = #{projectId}
AND report.workshop_id = #{workshopId}
AND report.in_year_month_date >= #{minYearMonth}
AND report.in_year_month_date <= #{maxYearMonth}
GROUP BY report.in_year_month_date
) a GROUP BY a.newYear_month ) mbcl_t ON ym_t.`year_month` = mbcl_t.newYear_month ORDER BY ym_t.`year_month`;

select a.project_id 'project.id', a.serial_number 'project.serialNumber', a.short_name 'project.shortName', ROUND(IFNULL(a.total_weight,0),2) schedulingWeight, ROUND(IFNULL(b.total_weight,0),2) steelFeedingWeight, ROUND(IFNULL(c.total_weight,0),2) steelReportWeight, ROUND(IFNULL(d.total_weight,0),2) profilesReportWeight from ( select task.project_id, cp.serial_number, cp.short_name, sum(task.task_quantity * part.net_weight) total_weight from mes_building_task task left join tech_machine_part part on task.product_id = part.id and part.bool_delete_enum = 0 left join contract_project cp on task.project_id = cp.id and cp.bool_delete_enum = 0 where task.bool_delete_enum = 0 and task.task_type_enum = 1
and task.workshop_id = #{workShopId}
and cp.status = #{projectStatus}
and cp.short_name like concat('%',#{projectName},'%')
and Year(task.create_time) = #{date}
GROUP BY task.project_id )a left join ( select project_id, sum(mete/1000) total_weight from mes_machine_part_raw_material_feeding_record where bool_delete_enum = 0
and Year(create_time) = #{date}
GROUP BY project_id )b on a.project_id = b.project_id left join ( select rep.project_id, Sum(rep.quantity * part.net_weight) total_weight from mes_building_produce_team_report rep left join tech_machine_part part on rep.product_id = part.id and part.bool_delete_enum = 0 left join mes_building_task_process pro on rep.task_process_id = pro.id and pro.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and rep.task_type_enum = 1 and pro.sequence = 0 and part.product_classification_enum = 8
and Year(rep.create_time) = #{date}
group by project_id )c on a.project_id = c.project_id left join ( select rep.project_id, Sum(rep.quantity * part.net_weight) total_weight from mes_building_produce_team_report rep left join tech_machine_part part on rep.product_id = part.id and part.bool_delete_enum = 0 left join mes_building_task_process pro on rep.task_process_id = pro.id and pro.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and rep.task_type_enum = 1 and pro.sequence = 0 and part.product_classification_enum = 4
and Year(rep.create_time) = #{date}
group by project_id )d on a.project_id = d.project_id left join ( select project_id,group_concat(branch_company_id) branchCompanyIds from project_branch_company_link where bool_delete_enum = 0 group by project_id )e on a.project_id = e.project_id
e.branchCompanyIds like concat('%',#{branchCompanyId},'%')

SELECT task.create_time createTime, pm.`name`, part.serial_number serialNumber, part.specification, task.task_quantity taskQuantity, part.net_weight netWeight, task.task_quantity * part.net_weight totalWeight FROM mes_building_task task LEFT JOIN contract_project cp ON task.project_id = cp.id AND cp.bool_delete_enum = 0 left join tech_machine_part part on task.product_id = part.id and part.bool_delete_enum = 0 left join plan_monomer pm on task.monomer_id = pm.id and pm.bool_delete_enum = 0 where task.bool_delete_enum = 0 and task.task_type_enum = 1
and task.project_id = #{projectId}
and task.workshop_id = #{workShopId}
and cp.status = #{projectStatus}
and cp.short_name like concat('%',#{projectName},'%')
and Year(task.create_time) = #{date}

select '1' type, '4' stuffType, mfr.specification, mfr.material, '1' quantity, ROUND(mfr.mete / 1000, 2) totalWeight, date_FORMAT(mfr.create_time, '%Y-%m-%d') feedingTime, su.`name` feedingUser from mes_machine_part_raw_material_feeding_record mfr left join sys_user su on mfr.create_user_id = su.id and su.bool_delete_enum = 0 where mfr.bool_delete_enum = 0
and mfr.project_id = #{projectId}
and Year(mfr.create_time) = #{date}

select date_FORMAT(rep.create_time,'%Y-%m-%d') createTime, su.`name` reportName, pm.`name` monomerName, part.serial_number serialNumber, part.specification, part.quantity, part.net_weight netWeight, rep.quantity * part.net_weight totalWeight from mes_building_produce_team_report rep left join tech_machine_part part on rep.product_id = part.id and part.bool_delete_enum = 0 left join mes_building_task_process pro on rep.task_process_id = pro.id and pro.bool_delete_enum = 0 left join sys_user su on rep.user_id = su.id and su.bool_delete_enum = 0 left join plan_monomer pm on rep.monomer_id = pm.id and pm.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and rep.task_type_enum = 1 and pro.sequence = 0
and part.product_classification_enum = #{partType}
and rep.project_id = #{projectId}
and rep.workshop_id = #{workShopId}
and Year(rep.create_time) = #{date}

select date_FORMAT(rep.create_time,'%Y-%m') date, sum(rep.quantity) quantity, sum(rep.quantity * art.net_weight) avgLineTon from mes_building_produce_team_report rep left join mes_building_task task on rep.task_id = task.id and task.bool_delete_enum = 0 left join tech_artifact art on task.product_id = art.id and art.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and rep.task_type_enum = 2
and rep.project_id = #{projectId}
and rep.workshop_id = #{workshopId}
and rep.production_line_id = #{productionLineId}
and rep.team_id = #{teamId}
AND rep.create_time >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y-%m-01') group by date_FORMAT(rep.create_time,'%Y-%m')

SELECT cp.serial_number, cp.short_name, ord.id orderId, ord.order_number, ord.ask_complete_time, sum(task.task_quantity - task.complete_quantity) uncompletedQuantity, sum((task.task_quantity - task.complete_quantity) * art.net_weight) uncompletedWeight FROM mes_building_task_order ord LEFT JOIN contract_project cp ON ord.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_task task ON ord.id = task.task_order_id AND task.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON task.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN mes_building_task_process pro on task.id = pro.task_id and pro.bool_delete_enum = 0 WHERE ord.bool_delete_enum = 0 AND task.task_type_enum = 2 and task.task_quantity - task.complete_quantity > 0
and ord.project_id = #{projectId}
and task.workshop_id = #{workshopId}
and task.production_line_id = #{productionLineId}
and pro.team_id = #{teamId}
GROUP BY cp.serial_number, cp.short_name, ord.id, ord.order_number, ord.ask_complete_time

SELECT ord.id orderId, cp.serial_number projectSerialNumber, cp.short_name projectName, pm.id monomerId, pm.name monomerName, area.id areaId, area.name areaName, art.serial_number, art.specification, art.material, art.length, task.task_quantity - task.complete_quantity uncompletedQuantity, art.net_weight FROM mes_building_task_order ord LEFT JOIN mes_building_task task ON ord.id = task.task_order_id AND task.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON task.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN contract_project cp ON task.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer pm on task.monomer_id = pm.id and pm.bool_delete_enum = 0 LEFT JOIN plan_area area on task.area_id = area.id and area.bool_delete_enum = 0 LEFT JOIN mes_building_task_process pro on task.id = pro.task_id and pro.bool_delete_enum = 0 WHERE ord.bool_delete_enum = 0 AND task.task_type_enum = 2 and task.task_quantity - task.complete_quantity > 0
and ord.id = #{orderId}
and pro.team_id = #{teamId}

SELECT cp.serial_number projectSerialNumber, cp.short_name projectName, pm.id monomerId, pm.name monomerName, area.id areaId, area.name areaName, art.serial_number, art.specification, art.material, art.length, task.task_quantity currentSchedulingQuantity, art.net_weight FROM mes_building_task task LEFT JOIN tech_artifact art ON task.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN contract_project cp ON task.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer pm on task.monomer_id = pm.id and pm.bool_delete_enum = 0 LEFT JOIN plan_area area on task.area_id = area.id and area.bool_delete_enum = 0 LEFT JOIN mes_building_task_process pro on task.id = pro.task_id and pro.bool_delete_enum = 0 WHERE task.bool_delete_enum = 0 AND task.task_type_enum = 2
and task.project_id = #{projectId}
and art.serial_number like concat('%',#{serialNumber},'%')
and pro.team_id = #{teamId}

SELECT a.projectId, a.serialNumber projectSerialNumber, a.projectName, a.monomerId, a.monomerName, a.areaId, a.areaName, a.`date`, a.quantity taskQuantity, a.totalNetWeight totalNetWeight, a.quantity - b.taskQuantity unScheTaskQuantity, a.totalNetWeight - b.totalNetWeight unScheTotalNetWeight FROM ( SELECT cp.id projectId, cp.serial_number serialNumber, cp.`name` projectName, pm.id monomerId, pm.`name` monomerName, pa.id areaId, pa.`name` areaName, pa.`date`, sum(artifact.quantity - artifact.purchase_quantity - artifact.subscription_quantity) quantity, sum((artifact.quantity - artifact.purchase_quantity - artifact.subscription_quantity) * artifact.net_weight) totalNetWeight FROM tech_artifact artifact LEFT JOIN contract_project cp ON artifact.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_area pa ON pa.id = artifact.area_id AND pa.bool_delete_enum = 0 LEFT JOIN plan_monomer pm ON pm.id = artifact.monomer_id AND pm.bool_delete_enum = 0 WHERE artifact.bool_delete_enum = 0 AND artifact.structure_class_id IS NOT NULL GROUP BY cp.id, pm.id, pa.id ORDER BY pa.id ) a JOIN ( SELECT sche.area_id, sum(sche.quantity) taskQuantity, sum(sche.quantity * art.net_weight) totalNetWeight FROM mes_building_artifact_scheduling sche LEFT JOIN tech_artifact art ON sche.product_id = art.id AND art.bool_delete_enum = 0 WHERE sche.bool_delete_enum = 0 GROUP BY sche.area_id ORDER BY sche.area_id ) b ON a.areaId = b.area_id where a.quantity - b.taskQuantity > 0
and a.projectId = #{projectId}
and a.monomerId = #{monomerId}

SELECT artifact.id product_id, artifact.`name`, artifact.serial_number, artifact.material, artifact.area_id 'area.id', pa.name 'area.name', artifact.monomer_id 'monomer.id', pm.name 'monomer.name', artifact.specification, artifact.length, artifact.net_weight, artifact.gross_weight, artifact.quantity, artifact.net_weight*artifact.quantity total_net_weight, artifact.gross_weight*artifact.quantity total_gross_weight, IFNULL(scheduling.scheduling_quantity,0) scheduling_quantity, IFNULL(scheduling.scheduling_quantity*artifact.net_weight,0) scheduling_total_net_weight, IFNULL(scheduling.scheduling_quantity*artifact.gross_weight,0) scheduling_total_gross_weight, artifact.quantity-artifact.subscription_quantity - artifact.purchase_quantity -IFNULL(scheduling.scheduling_quantity,0) un_scheduling_quantity, (artifact.quantity-artifact.subscription_quantity- artifact.purchase_quantity -IFNULL(scheduling.scheduling_quantity,0))*artifact.net_weight un_scheduling_total_net_weight, (artifact.quantity-artifact.subscription_quantity- artifact.purchase_quantity -IFNULL(scheduling.scheduling_quantity,0))*artifact.gross_weight un_scheduling_total_gross_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum(quantity) scheduling_quantity FROM mes_building_artifact_scheduling WHERE bool_delete_enum = 0 AND area_id = #{areaId} GROUP BY product_id ) scheduling ON scheduling.product_id = artifact.id LEFT JOIN plan_area pa ON pa.id = artifact.area_id LEFT JOIN plan_monomer pm ON pm.id = artifact.monomer_id WHERE artifact.bool_delete_enum = 0 AND artifact.structure_class_id is not null AND artifact.area_id = #{areaId}
AND artifact.structure_class_id IN
#{classId}
AND artifact.structure_class_id = #{structureClassId}
AND artifact.serial_number LIKE concat('%',#{serialNumber},'%')
AND artifact.name LIKE concat('%',#{name},'%')
AND artifact.material LIKE concat('%', #{material},'%')
AND artifact.specification LIKE concat('%', #{specification},'%')
AND (artifact.quantity - artifact.subscription_quantity - artifact.purchase_quantity - IFNULL(scheduling.scheduling_quantity,0)) > 0 ORDER BY artifact.specification ASC
